import { useEffect, useMemo, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import EmployeeInsuranceDataSection from './EmployeeInsuranceDataSection';
import InsuranceSummaryCards from './InsuranceSummaryCards';
import InsuranceList from '../insuranceList/InsuranceList';

export default function InsuranceInfoTab() {
    const [employeeInsuranceData, setEmployeeInsuranceData] = useState<any>(null);

    useEffect(() => {
        const fetchEmployeeInsuranceData = async () => {
            const response = await apiGet({ endpoint: endpoints.insurance.employee });
            if (response) {
                setEmployeeInsuranceData(response.data?.data);
            }
        };

        fetchEmployeeInsuranceData();
    }, []);

    const relatives = employeeInsuranceData?.relatives;

    const summary = useMemo(() => {
        const amount = employeeInsuranceData?.amount;
        const parsed = typeof amount === 'number' ? amount : Number(amount);
        const insuranceValue = Number.isFinite(parsed) && parsed > 0 ? parsed : 10_000;

        let beneficiariesCount = 3;
        if (employeeInsuranceData) {
            beneficiariesCount = Array.isArray(relatives) ? relatives.length : 0;
        }

        return { insuranceValue, beneficiariesCount };
    }, [employeeInsuranceData, relatives]);

    return (
        <div className="w-full mt-6">
            <InsuranceSummaryCards
                insuranceValue={summary.insuranceValue}
                beneficiariesCount={summary.beneficiariesCount}
            />

            <EmployeeInsuranceDataSection employeeInsuranceData={employeeInsuranceData} />
            <InsuranceList />
        </div>
    );
}
