import { ColumnDef, Row } from '@tanstack/react-table';
import { Customer } from '@/types/customer.types';
import TrashIcon from '@/components/icons/TrashIcon';
import { useState } from 'react';
import EditIcon from '@/components/icons/EditIcon';

export type InsuranceBeneficiaryColumnHandlers = {
    onEditBeneficiary: (row: Customer) => void;
};

function createActionsCell(onEditBeneficiary: (row: Customer) => void) {
    return function ActionsCell({ row }: { row: Row<Customer> }) {
        const [showDeletePopup, setShowDeletePopup] = useState(false);

        return (
            <div className="me-6 text-end">
                <button
                    type="button"
                    onClick={() => onEditBeneficiary(row.original)}
                    className="text-primary hover:text-primary/80"
                >
                    <EditIcon className="text-primery-blue-400" />
                </button>
                <button
                    type="button"
                    className="hover:bg-white-blue-300 rounded-full p-1"
                    onClick={() => setShowDeletePopup(true)}
                >
                    <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                </button>
            </div>
        );
    };
}

export function createInsuranceBeneficiaryColumns({
    onEditBeneficiary,
}: InsuranceBeneficiaryColumnHandlers): ColumnDef<Customer>[] {
    const ActionsCell = createActionsCell(onEditBeneficiary);

    return [
    {
        accessorKey: 'id',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    رقم المشترك
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.id}
            </div>
        ),
    },
    {
        accessorKey: 'name',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    اسم المشترك
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.full_name}
            </div>
        ),
    },
    {
        accessorKey: 'status',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    نوع التأمين
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {/* {row.original.phone} */}
                </div>
            );
        },
    },
    {
        accessorKey: 'date',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    تاريخ بدء الاشتراك
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {/* {row.original.address} */}
                </div>
            );
        },
    },
    {
        accessorKey: 'service',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    تاريخ انتهاء الاشتراك
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {/* {row.original.personal_id_number} */}
                </div>
            );
        },
    },
    {
        accessorKey: 'location',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    قيمة الاشتراك
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {/* {row.original.driver_license_number} */}
                </div>
            );
        },
    },
    {
        accessorKey: 'location',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    الحالة
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-sm text-[#625E74] font-normal tracking-normal leading-[26.4px]">
                    {row.original?.rent_days}
                </div>
            );
        },
    },
    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    مشاهدة
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
}