import { z } from 'zod';

export const AddInsuranceSchema = z.object({
    name: z.string().min(1, 'الاسم مطلوب'),
    subscriber_number: z.string(),
    identity_number: z.string().min(1, 'رقم الهوية مطلوب'),
    birth_date: z.date({ required_error: 'تاريخ الميلاد مطلوب' }),
    note: z.string().optional(),
    attachment: z
        .custom<File | undefined>()
        .optional()
        .refine(
            (file) => {
                if (!file) return true;
                return file.type === 'application/pdf';
            },
            { message: 'يجب أن يكون الملف بصيغة PDF' },
        )
        .refine(
            (file) => {
                if (!file) return true;
                return file.size <= 10 * 1024 * 1024;
            },
            { message: 'يجب ألا يتجاوز حجم الملف 10 ميجابايت' },
        ),
});

export type AddInsuranceFormValues = z.infer<typeof AddInsuranceSchema>;
