import { useEffect, useMemo, useState } from 'react';
import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { format } from 'date-fns';
import { toast } from 'sonner';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import TextInputForm from '@/components/forms/TextInputForm';
import { DateInputForm } from '@/components/forms/DateInputForm';
import TextAreaInputForm from '@/components/forms/TextAreaInputForm';
import FileInput from '@/features/selfServices/forms/services/FileInput';
import { cn } from '@/lib/utils';
import { apiPost, apiPut } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import SuccessIcon from '@/components/icons/SuccessIcon';
import EditIcon from '@/components/icons/EditIcon';
import { AddInsuranceSchema, AddInsuranceFormValues } from '../schemas/add-insurance-schema';
import Submission from './Submission';

export type BeneficiaryInitialValues = {
    name: string;
    identity_number: string;
    subscriber_number?: string;
    birth_date?: Date | string;
    note?: string;
};

type AddBeneficiaryDialogProps = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    insuranceId?: string;
    subscriberNumber?: string;
    beneficiaryId?: string | number;
    initialValues?: BeneficiaryInitialValues;
    onSaved?: () => void;
};

function parseBirthDate(value?: Date | string): Date | undefined {
    if (value == null || value === '') return undefined;
    if (value instanceof Date) return value;
    const d = new Date(value);
    return Number.isNaN(d.getTime()) ? undefined : d;
}

export function AddBeneficiaryDialog({
    open,
    onOpenChange,
    insuranceId,
    subscriberNumber = '87890',
    beneficiaryId,
    initialValues,
    onSaved,
}: AddBeneficiaryDialogProps) {
    const isEdit = beneficiaryId != null;
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);

    const defaultValues = useMemo(
        () => ({
            name: '',
            subscriber_number: subscriberNumber,
            identity_number: '',
            birth_date: undefined as unknown as Date,
            note: '',
            attachment: undefined as File | undefined,
        }),
        [subscriberNumber],
    );

    const form = useForm<AddInsuranceFormValues>({
        resolver: zodResolver(AddInsuranceSchema),
        defaultValues,
    });

    const editResetKey =
        isEdit && initialValues
            ? `${beneficiaryId}|${initialValues.name}|${initialValues.identity_number}|${initialValues.subscriber_number ?? ''}|${String(initialValues.birth_date ?? '')}|${initialValues.note ?? ''}`
            : '';

    useEffect(() => {
        if (!open) return;
        setError(null);
        if (isEdit && initialValues) {
            const birth = parseBirthDate(initialValues.birth_date);
            form.reset({
                name: initialValues.name,
                subscriber_number: initialValues.subscriber_number ?? String(beneficiaryId),
                identity_number: initialValues.identity_number,
                birth_date: (birth ?? undefined) as unknown as Date,
                note: initialValues.note ?? '',
                attachment: undefined,
            });
        } else {
            form.reset({
                name: '',
                subscriber_number: subscriberNumber,
                identity_number: '',
                birth_date: undefined as unknown as Date,
                note: '',
                attachment: undefined,
            });
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- reset when dialog opens or edit target changes (editResetKey), not when initialValues identity changes every render
    }, [open, subscriberNumber, form, isEdit, beneficiaryId, editResetKey]);

    const resetForClose = () => {
        form.reset(defaultValues);
        setError(null);
    };

    const handleOpenChange = (next: boolean) => {
        if (!next) resetForClose();
        onOpenChange(next);
    };

    const onSubmit = async (data: AddInsuranceFormValues) => {
        if (!isEdit && !insuranceId) {
            toast.error('معرف التأمين غير متوفر. يرجى ربط الصفحة بتأمين الموظف لإكمال الطلب.');
            return;
        }

        setLoading(true);
        setError(null);
        try {
            const fd = new FormData();
            if (insuranceId) {
                fd.append('insurance_id', insuranceId);
            }
            fd.append('name', data.name);
            fd.append('identity_number', data.identity_number);
            fd.append('birth_date', format(data.birth_date, 'yyyy-MM-dd'));
            fd.append('note', data.note ?? '');
            fd.append('amount', '0');
            fd.append('phone', data.identity_number);
            fd.append('relationship', 'تابع');
            if (data.attachment) {
                fd.append('attachment', data.attachment);
            }

            if (isEdit) {
                await apiPut({
                    endpoint: endpoints.insuranceRelatives.update + beneficiaryId,
                    body: fd,
                    config: { headers: { 'Content-Type': 'multipart/form-data' } },
                });
                toast.success('تم حفظ التعديلات بنجاح', {
                    duration: 3000,
                    className: 'font-cairo',
                    icon: <SuccessIcon width="25" height="25" className="text-green-success-600" />,
                });
            } else {
                await apiPost({
                    endpoint: endpoints.insuranceRelatives.create,
                    body: fd,
                    config: { headers: { 'Content-Type': 'multipart/form-data' } },
                });
                toast.success('تم تقديم الطلب بنجاح', {
                    duration: 3000,
                    className: 'font-cairo',
                    icon: <SuccessIcon width="25" height="25" className="text-green-success-600" />,
                });
            }

            onSaved?.();
            handleOpenChange(false);
        } catch (err: unknown) {
            const axiosErr = err as { response?: { data?: { msg?: string; errors?: Record<string, string[]> } } };
            if (axiosErr.response?.data?.errors) {
                Object.entries(axiosErr.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as keyof AddInsuranceFormValues, {
                        type: 'manual',
                        message: messages.join(', '),
                    });
                });
            } else {
                const msg = axiosErr.response?.data?.msg ?? 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                setError(msg);
            }
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={handleOpenChange}>
            <div
                className={cn('fixed inset-0', {
                    '!hidden': !open,
                })}
            />
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                className="max-w-[623px] max-h-[90vh] overflow-y-auto rounded-lg p-8 bg-white-blue-50 font-cairo gap-0 [&_[aria-label=Close]]:opacity-0"
            >
                <DialogHeader className="flex flex-col items-stretch">
                    <div className="flex flex-row justify-between mb-4 w-full">
                        <div className="flex flex-row gap-2 items-center">
                            {isEdit ? (
                                <EditIcon width="25" height="25" className="text-primery-blue-500" />
                            ) : (
                                <PlusIcon />
                            )}
                            <h3 className="text-[22px] font-bold text-primery-blue-500">
                                {isEdit ? 'تعديل بيانات مستفيد' : 'اضافة بيانات مستفيد'}
                            </h3>
                        </div>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1] !mt-0" />
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                        {error && (
                            <div className="mb-4 p-4 bg-red-error-50 border border-red-error-200 text-red-error-700 rounded-lg text-sm">
                                {error}
                            </div>
                        )}

                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-6 gap-y-4">
                            <TextInputForm name="name" label="الاسم" placeholder="محمد احمد" />
                            <TextInputForm
                                name="subscriber_number"
                                label="رقم المشترك"
                                placeholder={subscriberNumber}
                                disabled
                            />
                            <TextInputForm name="identity_number" label="رقم الهوية" placeholder="215698423" />
                            <DateInputForm name="birth_date" label="تاريخ الميلاد" placeholder="2004/04/30" />
                        </div>

                        <div className="mt-4">
                            <TextAreaInputForm
                                className="flex flex-col min-h-[120px]"
                                name="note"
                                label="ملاحظات"
                                placeholder="اكتب ملاحظات اضافية"
                            />
                        </div>

                        <div className="mt-4">
                            <FileInput name="attachment" label="رفع ملف" multiple={false} maxSize={10 * 1024 * 1024} />
                            <p className="text-xs text-[#90868C] mt-2 leading-relaxed">
                                يجب ان يكون حجم الملف لا يتجاوز 10 ميجا وبكون صيغته PDF
                            </p>
                        </div>

                        <div className="flex flex-row gap-4 mt-8">

                            <Submission
                                isEdit={isEdit}
                                loading={loading}
                                setShowCancelPopup={setShowCancelPopup}
                                setShowSuccessPopup={setShowSuccessPopup}
                                showCancelPopup={showCancelPopup}
                                showSuccessPopup={showSuccessPopup}
                                onCloseDialog={() => handleOpenChange(false)}
                            />
                        </div>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}
