import { useCallback, useMemo, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar, type DataTableToolbarProps } from './data-table-toolbar';
import { Car } from '@/types/cars.types';
import { createInsuranceBeneficiaryColumns } from './columns';
import { FetchDataOptions } from '@/types/table.types';
import { DataTable } from '@/components/tables/customTable/data-table';
import { AddBeneficiaryDialog, BeneficiaryInitialValues } from './AddBeneficiaryDialog';
import { Customer } from '@/types/customer.types';

type EditBeneficiaryState = BeneficiaryInitialValues & {
    id: number;
    refreshTable?: () => void;
};

type InsuranceListProps = {
    insuranceId?: string;
};

const InsuranceList = ({ insuranceId }: InsuranceListProps) => {
    const [data, setData] = useState<Car[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [editBeneficiary, setEditBeneficiary] = useState<EditBeneficiaryState | null>(null);

    const columns = useMemo(
        () =>
            createInsuranceBeneficiaryColumns({
                onEditBeneficiary: (row: Customer) => {
                    setEditBeneficiary({
                        id: row.id,
                        name: row.full_name,
                        identity_number: row.personal_id_number ?? '',
                        subscriber_number: String(row.id),
                        note: '',
                        refreshTable: row.refreshTable,
                    });
                },
            }),
        [],
    );

    // Use useCallback to ensure the function reference is stable
    const fetchData = useCallback(async (options: FetchDataOptions) => {
        setIsLoading(true);
        try {
            const response = await apiGet({
                endpoint: endpoints.customer.list,
                queryParams: { page: options.pageIndex + 1, ...options.filters, search: options.globalFilter },
            });

            setData(response.data.data.data);
            setPageCount(Math.ceil(response.data.data.pagination.total / 10));
            setTotalCount(response.data.data.pagination.total);
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    }, []);

    const editInitial: BeneficiaryInitialValues | undefined = editBeneficiary
        ? {
              name: editBeneficiary.name,
              identity_number: editBeneficiary.identity_number,
              subscriber_number: editBeneficiary.subscriber_number,
              birth_date: editBeneficiary.birth_date,
              note: editBeneficiary.note,
          }
        : undefined;

    const handleEditSaved = () => {
        editBeneficiary?.refreshTable?.();
    };

    return (
        <div className="mb-10 mt-4 rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <AddBeneficiaryDialog
                open={!!editBeneficiary}
                onOpenChange={(open) => {
                    if (!open) setEditBeneficiary(null);
                }}
                beneficiaryId={editBeneficiary?.id}
                initialValues={editInitial}
                insuranceId={insuranceId}
                subscriberNumber={editBeneficiary?.subscriber_number}
                onSaved={handleEditSaved}
            />
            <DataTable
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={(props: DataTableToolbarProps) => (
                    <DataTableToolbar {...props} insuranceId={insuranceId} />
                )}
                isLoading={isLoading}
            />
        </div>
    );
};

export default InsuranceList;
