import { useState } from 'react';
import { Table } from '@tanstack/react-table';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import AddIcon from '@/components/icons/AddIcon';
import ArrowBackIcon from '@/components/icons/ArrowBackIcon';
import { Customer } from '@/types/customer.types';
import { Filters } from '@/types/table.types';
import { AddBeneficiaryDialog } from './AddBeneficiaryDialog';

export interface DataTableToolbarProps {
    table: Table<Customer>;
    globalFilter: string;
    setGlobalFilter: (value: string) => void;
    filters: Filters;
    setFilters: (value: Filters) => void;
    /** عند توفره يُرسل مع طلب إضافة المستفيد */
    insuranceId?: string;
    subscriberNumber?: string;
}

export function DataTableToolbar({
    globalFilter,
    setGlobalFilter,
    filters,
    setFilters,
    insuranceId,
    subscriberNumber,
}: DataTableToolbarProps) {
    const [addBeneficiaryOpen, setAddBeneficiaryOpen] = useState(false);

    return (
        <>
            <AddBeneficiaryDialog
                open={addBeneficiaryOpen}
                onOpenChange={setAddBeneficiaryOpen}
                insuranceId={insuranceId}
                subscriberNumber={subscriberNumber}
            />
            <div className="flex flex-col p-2 sm:flex-row sm:items-center sm:justify-between">
                <UnderlineHeading text="المستفيدين من التأمينات" />
                <div className="flex flex-row items-center gap-4">
                    <div>
                        <PrimaryButton
                            type="button"
                            onClick={() => setAddBeneficiaryOpen(true)}
                            className="text-base px-[14px] xl:py-2 leading-5 font-semibold font-cairo tracking-normal"
                        >
                            <AddIcon />
                            <p className="text-xs tracking-normal font-normal leading-[22.49px]">إضافة مستفيد</p>
                        </PrimaryButton>
                    </div>
                    <div className="flex items-center justify-center gap-2 px-[14px] py-2 bg-primery-blue-50 border border-primery-blue-50 shadow-[0px_1px_2px_0px_#1018280D] rounded-lg ">
                        <ArrowBackIcon className="text-primery-blue-700" />
                        <p className="text-xs text-primery-blue-500 tracking-normal font-normal leading-[22.49px]">
                            تصدير
                        </p>
                    </div>
                </div>
            </div>
            {/* <DataTableViewOptions table={table} /> */}
        </>
    );
}
