import StatisticsCards from '@/components/cards/StatisticsCards';
import UserMinusIcon from '@/components/icons/UserMinusIcon';
import { Card } from '@/types/statistics';

type Props = {
    insuranceValue?: number;
    beneficiariesCount?: number;
};

export default function InsuranceSummaryCards({
    insuranceValue = 10_000,
    beneficiariesCount = 3,
}: Props) {
    const cards: Card[] = [
        {
            text: 'قيمة التأمين',
            icon: <UserMinusIcon />,
            num: insuranceValue,
            label: 'ر.س',
            percent: -0.3,
        },
        {
            text: 'عدد المستفيدين',
            icon: <UserMinusIcon />,
            num: beneficiariesCount,
            percent: -0.3,
        },
    ];

    return <StatisticsCards cards={cards} numJustifyStart={true} />;
}
